package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class CycleTests {
 static int checks;static void check(boolean value,String label){if(!value)throw new AssertionError(label);checks++;}
 static String run(Document d){FlowEngine.Runner r=new FlowEngine.Runner(d);for(int i=0;i<500&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++)r.step();check(r.state==FlowEngine.State.COMPLETED,"Run completes: "+r.errorMessage);return String.join("|",r.output);}
 static String topology(Document d){String s="";for(Node n:d.nodes)s+=n.id+":"+n.kind+"|";for(Edge e:d.edges)s+=e.id+":"+e.from+":"+e.to+":"+e.branch+"|";return s;}
 static InfoPair loop(int kind){Document b=FlowExamples.blank();Document d=FlowLoopBuilder.prepare(b,null,b.edges.get(0).id,FlowLoopBuilder.Spec.defaults(kind)).project;return new InfoPair(d,FlowCycle.find(d).get(0));}
 static final class InfoPair {Document d;FlowCycle.Info info;InfoPair(Document d,FlowCycle.Info i){this.d=d;info=i;}}
 public static void main(String[] args)throws Exception{Path out=Paths.get(args[0]);
  for(int kind=0;kind<3;kind++){InfoPair pair=loop(kind);Document d=pair.d;for(Node n:d.nodes){n.comment="nota "+n.kind;n.breakpoint=true;n.breakpointCondition="vero";if(n.kind==DECISION)n.trueLabel="Dentro";}FlowCycle.Info info=FlowCycle.find(d).get(0);check(info.kind==kind,"Recognize kind "+kind);String before=FlowCodec.encode(d),edges=topology(d);if(kind==0)info.spec.to="3";else info.spec.condition="i < 3";FlowLoopBuilder.Plan plan=FlowCycle.prepare(d,null,info,info.spec);check(before.equals(FlowCodec.encode(d)),"Original immutable");check(edges.equals(topology(plan.project)),"All node and edge identifiers unchanged");String expected=kind==0?"1|2|3":"0|1|2";check(run(plan.project).equals(expected),"New semantics "+kind);check(FlowCycle.find(plan.project).get(0).kind==kind,"Remains editable");for(Node n:d.nodes){Node now=plan.project.find(n.id);check(Objects.equals(n.comment,now.comment)&&n.breakpoint==now.breakpoint&&Objects.equals(n.breakpointCondition,now.breakpointCondition)&&n.trueLabel.equals(now.trueLabel),"Metadata retained");if(!info.members.contains(n.id)&&n.kind!=END)check(n.x==now.x&&n.y==now.y,"Upstream fixed");}Files.write(out.resolve("android-cycle-"+kind+".frociart"),FlowCodec.encode(plan.project).getBytes(StandardCharsets.UTF_8));check(run(FlowCodec.decode(new String(Files.readAllBytes(out.resolve("pc-cycle-"+kind+".frociart")),StandardCharsets.UTF_8))).equals(expected),"PC result runs on Android");
   if(kind==0){FlowCycle.Info dynamic=FlowCycle.find(plan.project).get(0);dynamic.spec.step="int(2)";FlowLoopBuilder.Plan changed=FlowCycle.prepare(plan.project,null,dynamic,dynamic.spec);check(run(changed.project).equals("1|3"),"Dynamic step");FlowCycle.Info back=FlowCycle.find(changed.project).get(0);back.spec.step="1";check(run(FlowCycle.prepare(changed.project,null,back,back.spec).project).equals("1|2|3"),"Dynamic back to constant");FlowCycle.Info bad=FlowCycle.find(d).get(0);bad.spec.step="0";boolean rejected=false;try{FlowCycle.prepare(d,null,bad,bad.spec);}catch(IllegalArgumentException e){rejected=true;}check(rejected&&before.equals(FlowCodec.encode(d)),"Invalid edit leaves original intact");}
  }
  Document nested=FlowPseudocode.decode("INIZIO\nPER i DA 1 A 2 FAI\nPER j DA 1 A 2 FAI\nSTAMPA i * 10 + j\nFINE PER\nFINE PER\nFINE");List<FlowCycle.Info> groups=FlowCycle.find(nested);check(groups.size()==2,"Nested cycles separate");groups.sort(Comparator.comparingInt(c->c.members.size()));FlowCycle.Info inner=groups.get(0);inner.spec.to="3";check(run(FlowCycle.prepare(nested,null,inner,inner.spec).project).equals("11|12|13|21|22|23"),"Nested edit");
  Document unsafe=nested.copy();FlowCycle.Info outer=FlowCycle.find(unsafe).stream().max(Comparator.comparingInt(c->c.members.size())).get();Node start=unsafe.nodes.stream().filter(n->n.kind==START).findFirst().get();unsafe.edges.add(new Edge(start.id,outer.bodyEntry,"next"));check(FlowCycle.find(unsafe).stream().noneMatch(i->i.kind==0&&i.entry.equals(outer.entry)),"Unsafe entrances do not get grouped");
  Document fn=FlowPseudocode.decode("FUNZIONE f(n: INTERO) -> INTERO risultato\nrisultato=0\nPER i DA 1 A n FAI\nrisultato=risultato+i\nFINE PER\nFINE FUNZIONE\nINIZIO\nSTAMPA f(4)\nFINE");Function f=fn.functions.get(0);FlowCycle.Info fi=FlowCycle.find(f.body).get(0);fi.spec.to="2";FlowLoopBuilder.Plan fp=FlowCycle.prepare(fn,f.id,fi,fi.spec);check(run(fp.project).equals("3")&&topology(fn).equals(topology(fp.project)),"Function edit leaves main alone");
  InfoPair lp=loop(0);lp.info.spec.to="1"+String.join("",Collections.nCopies(60,"+1"));lp.info.spec.step="int(2)";Document grown=FlowCycle.prepare(lp.d,null,lp.info,lp.info.spec).project;for(int i=0;i<grown.nodes.size();i++)for(int k=i+1;k<grown.nodes.size();k++){Node a=grown.nodes.get(i),b=grown.nodes.get(k);check(a.x>=b.x+width(b)||a.x+width(a)<=b.x||a.y>=b.y+height(b)||a.y+height(a)<=b.y,"Larger helpers do not overlap");}
  FlowCycle.Info ni=FlowCycle.find(nested).stream().min(Comparator.comparingInt(c->c.members.size())).get();ni.spec.to="1"+String.join("",Collections.nCopies(60,"+1"));ni.spec.step="int(2)";Document ng=FlowCycle.prepare(nested,null,ni,ni.spec).project;for(int i=0;i<ng.nodes.size();i++)for(int k=i+1;k<ng.nodes.size();k++){Node a=ng.nodes.get(i),b=ng.nodes.get(k);check(a.x>=b.x+width(b)||a.x+width(a)<=b.x||a.y>=b.y+height(b)||a.y+height(a)<=b.y,"Nested helper growth avoids enclosing continuation");}
  for(String s:new String[]{"non (\"(\" == \"(\")","non (\"a)\" == \"a)\")","non (vero) e (falso)"})check(FlowEngine.evaluate(FlowCycle.negate(s),Collections.emptyMap()).format().equals(FlowEngine.evaluate("non ("+s+")",Collections.emptyMap()).format()),"Quoted condition negation");
  Document nulls=FlowExamples.blank();nulls.nodes.add(new Node(PROCESS,null,0,0));check(FlowCycle.find(nulls).isEmpty(),"Null legacy operation does not crash cycle inventory");
  System.out.println("CYCLES_ANDROID PASS checks="+checks);
 }
}
